{
  "name": "通用实验探测器",
  "name_en": "Generic Laboratory Detector",
  "manufacturer": "",
  "description": "一种用于实验室测量的数据探测设备，泛指可输出测量信号或图像的检测仪器，如光电探测器、相机或其他科学传感器。它通常用于采集单次或连续实验数据，并将结果提供给实验控制与分析系统。",
  "description_en": "A laboratory measurement detector used to acquire experimental signals or images, broadly covering instruments such as photodetectors, cameras, or other scientific sensors. It is typically used for single-shot or continuous data acquisition and provides measurement results to laboratory control and analysis systems.",
  "actions": [
    {
      "action_name": "auto-update_settings",
      "description": "配置探测器的采集与运行参数。",
      "description_en": "Configure the detector's acquisition and operating settings."
    },
    {
      "action_name": "auto-queue_command",
      "description": "向探测器发送控制命令。",
      "description_en": "Send a control command to the detector."
    },
    {
      "action_name": "auto-ini_detector",
      "description": "初始化探测器并准备开始测量。",
      "description_en": "Initialize the detector and prepare it for measurement."
    },
    {
      "action_name": "auto-emit_temp_data",
      "description": "输出探测器产生的临时测量数据。",
      "description_en": "Output temporary measurement data produced by the detector."
    },
    {
      "action_name": "auto-data_ready",
      "description": "输出已完成采集的测量数据。",
      "description_en": "Output measurement data after acquisition is complete."
    },
    {
      "action_name": "auto-single",
      "description": "执行一次单次采集。",
      "description_en": "Perform a single acquisition."
    },
    {
      "action_name": "auto-grab_data",
      "description": "采集探测器数据，可用于单次或连续采集。",
      "description_en": "Acquire detector data for single-shot or continuous acquisition."
    },
    {
      "action_name": "auto-close",
      "description": "关闭探测器或结束当前连接与采集。",
      "description_en": "Close the detector or end the current connection and acquisition."
    }
  ],
  "tag_hints": [
    "scientific detector",
    "sensor readout",
    "single-shot acquisition",
    "live data acquisition",
    "laboratory measurement",
    "experimental data collection"
  ]
}

